        "silent": "內建預設不可編輯；拖動推子會切到「自定義 1」並寫入新值。重要設定請先切到「自定義 2」。",
        "reset": "清空當前自定義槽，恢復平直曲線和中性效果。內建預設不能編輯，所以選中時按鈕是灰的。",
        "effects": "推子下方是高低切、飽和、壓縮、抖晃、噪聲、立體聲寬度、空間和衝擊。同一自定義槽共用這套效果鏈。",
