        "pause": "預覽右下角那顆按鈕把畫面凍在當前這一幀。調那種只閃一下的效果時用得上，順帶也讓預覽在你讀字的時候不再繼續吃算力。",
        "invisible": "預覽上有三塊隱藏點選區，沒有邊框、底色或標籤。",
