        "four": "設定欄一共四頁：通用、背景、動畫、字幕。熱區指向的就是其中三頁，所以標籤和畫面是同一份清單的兩個入口。",
        "common": "只有一個例外：「通用」沒有自己的熱區，因為它不是畫面的一部分 —— 它裝的是作用於整屏的那些。那一頁只能從這排標籤進。",
        "fonts": "「通用」設定歌詞字型、字號和字重。字重預設自動，也可手動指定。",
        "previewText": "第一行挑的是預覽唱什麼。想看看這套字撐不撐得住長句、或者別的文字系統，換一段示例比等一首真歌放到那兒要快。",
        "sectionReset": "每一頁右上角各有一顆自己的復位，它退的只有這一頁。它不是整張調參臺的復位 —— 你在別的頁上調過的東西不會被它帶走。",
        "animation": "動畫那一頁最上面是模式本身。模式比這一屏能列下的多，而且值得你自己翻一遍，所以這一章只說這一頁是什麼，不把清單念一遍。",
        "perMode": "模式下方是對應引數；換模式，引數也會跟著換。",
