        "subtitleContent": "字幕第二行可選：無、翻譯、羅馬音，或羅馬音在上、翻譯在下的兩行。莫奈、時計和靜止選兩行時只顯示翻譯。",
        "subtitleLegibility": "這裡設定字幕底色、不透明度，以及未唱行的模糊效果。",
