        "current": "正在播放的那張卡上，播放鍵變成暫停 / 繼續，旁邊多出一個「進入」按鈕，去播放頁或 Lattice。",
        "keep": "從播放頁或 Lattice 回來，或者返回到這一層時，正在播放的那首會自己重新展開。按 Esc 或點空白牆面收起之後，就不再保持。",
