        "queueRadioActions": "底部按鈕用於丟棄或喜歡。丟棄後服務不會再播放這首，電臺會繼續下一首。",
        "cover": "面板頂部是當前歌曲的方形封面，換頁時保持不動。懸停後四角會出現按鈕。",
        "tabs": "封面下方是標籤頁：封面、控制、佇列、帳號；有來源資訊時還會多一個來源頁。換頁不會移動面板。",
