        "sourceTab": "本地、Navidrome 或線上來源的歌曲才會顯示來源頁；沒有來源資訊時只顯示四個標籤。",
        "sourceInfo": "來源頁顯示本地檔案資訊或 Navidrome 的 Song ID；線上來源沒有這一頁。",
