        "sourceLyrics": "右側兩顆圖示分別是匯入 / 匯出和線上匹配。下方顯示當前歌詞，匯入後可以切換回其他版本。",
        "sourceOffset": "時間軸偏移按 250ms 調整，也可以直接輸入。它只對當前播放生效；設定裡的全域性偏移會與它相加。",
        "sourceLyricsFile": "歌詞行左邊這顆是匯入 / 匯出：兩件事合在一個視窗裡，點開再選。",
        "sourceExportFormats": "視窗上面是匯入，接受 lrc、vtt、ttml、qrc、yrc、krc、txt 和 Folia 匯出的 .fia；Navidrome 的歌曲不能匯入，視窗裡只有匯出。中間兩塊把這一首導成檔案：.fia 保留逐字時間軸、翻譯、背景和聲和你儲存的分詞，能原樣導回來；.lrc 是增強型 LRC，別的播放器也能讀，但這些 Folia 專有的資訊會丟掉。",
        "sourceExportBatch": "最底下一行是批次匯出：它會開啟命令面板裡的匯出頁，一次匯出本機快取的所有歌詞。設定 · 儲存裡歌詞快取那一行也有同一個入口。",
        "coverTab": "封面頁放的是當前這首歌的文字資訊：歌名、歌手、專輯，居中排一列。大封面不在這一頁裡，它常駐在面板頂上。",
        "coverTabDetail": "點選歌手或專輯可進入對應集合。點選歌名複製歌曲資訊，按住 Ctrl 點選可開啟來源頁面。",
        "controlsTab": "控制頁最上面是三顆大按鈕：迴圈模式、喜歡、生成主題。這是整塊面板裡唯一一排大觸控目標。",
        "controlsTabDetail": "控制頁有音量、均衡器、自動混音、歌詞動畫、背景和主題設定。音訊增益與歌詞偏移在來源頁。",
        "queueTab": "佇列頁是當前播放佇列的完整列表，頂上一行寫著佇列裡有多少首。",
        "queueTabDetail": "點選歌曲即可播放；懸停後可移到下一首、移到隊尾或移除。頂部按鈕可開啟 Lattice 或打亂佇列。這裡不能拖動排序。",
        "accountTab": "帳號頁管的是當前音樂來源那一側的事。",
        "accountTabDetail": "帳號頁顯示登入狀態、音質檔位和雲同步。不同來源會顯示各自的帳號資訊。"
